+function describeError(error: unknown): string {
+  if (error instanceof Error) {
+    const details = error as Error & {
+      code?: unknown
+      errno?: unknown
+      syscall?: unknown
+      address?: unknown
+      port?: unknown
+    }
+    return inspect(
