+        name: details.name,
+        code: details.code,
+        errno: details.errno,
+        syscall: details.syscall,
+        address: details.address,
+        port: details.port,
+      },
+      { depth: 0, breakLength: Infinity },
+    )
+  }
+  return typeof error
+}
